$ErrorActionPreference='Stop'; $root=Split-Path -Parent $PSScriptRoot; $extension=Join-Path $root 'apps\vscode-extension'; $report=Join-Path $root 'artifacts\test-results\stage05-extension-host-e2e.json'
try { & powershell.exe -ExecutionPolicy Bypass -File (Join-Path $root 'scripts\build-extension.ps1'); if($LASTEXITCODE){throw 'build-extension failed'}; Push-Location $extension; node test/runBugLifecycleE2E.js; $code=$LASTEXITCODE; Pop-Location; if($code){throw "E2E failed: $code"}; if((Get-Content $report -Raw|ConvertFrom-Json).status -ne 'passed'){throw 'report failed'}; 'STAGE5_EXTENSION_HOST_BUG_E2E=PASS' } catch { Write-Error "STAGE5_EXTENSION_HOST_BUG_E2E=FAIL: $($_.Exception.Message)"; exit 1 }
